function json(status,data){return new Response(JSON.stringify(data),{status,headers:{...NO_CACHE,'Content-Type':'application/json; charset=utf-8'}});}
function limitedEqual(a,b){
  const left=new TextEncoder().encode(String(a));const right=new TextEncoder().encode(String(b));
  let diff=left.length^right.length;const len=Math.max(left.length,right.length);
  for(let i=0;i<len;i++)diff|=(left[i]||0)^(right[i]||0);
  return diff===0;
}
function hostName(env){const h=String(env.BLYNK_HOST||'blynk.cloud').trim().toLowerCase();if(!/^(?:[a-z0-9-]+\.)?blynk\.cloud$/.test(h))throw Error('BLYNK_HOST no es valid');return h;}
function settings(env){const n=Number(env.MAX_FOLLOWERS||4);return Number.isInteger(n)&&n>=1&&n<=250?n:4;}
function cleanValues(all){const out={};for(const v of ['v1','v2','v3','v4','v5']){
  const x=all[v]??all[v.toUpperCase()]??null;
  out[v]=x==null?null:String(typeof x==='object'?JSON.stringify(x):x).slice(0,1400);
}return out;}
async function blynk(env,path,query){
  const u=new URL('https://'+hostName(env)+path);
  u.searchParams.set('token',String(env.BLYNK_TOKEN));
  if(query)for(const [k,v] of Object.entries(query))u.searchParams.set(k,String(v));
  let r;try{r=await fetch(u.href,{method:'GET',redirect:'follow',signal:AbortSignal.timeout(14000),headers:{Accept:'application/json, text/plain, */*'}});}
  catch(_){throw Error('Blynk no respon per HTTPS; comprova Internet i el servidor regional');}
  if(!r.ok)throw Error('Blynk ha retornat HTTP '+r.status+' (comprova el token, el pin o la xarxa)');
  return r.text();
}
function boundInt(v,min,max){return typeof v==='number'&&Number.isSafeInteger(v)&&v>=min&&v<=max;}
function newId(){
  // Identificador de 12 digits. Una mateixa ordre repetida te un ID diferent.
  const t=String(Date.now()).slice(-10);
  const n=crypto.getRandomValues(new Uint8Array(1))[0]%100;
  return t+String(n).padStart(2,'0');
}
function commandBody(data,env){
  if(!data||typeof data!=='object')throw Error('Dades de l’ordre incorrectes');
  const kind=data.kind,seg=data.seg,fun=data.fun,val=data.val;
  const max=settings(env);
  const specialId=newId();
  if(kind==='countGet')return {id:specialId,command:'C:'+specialId};
  if(kind==='countSet'){
    if(String(env.ALLOW_CHANGES||'NO').toUpperCase()!=='YES')throw Error('Configuració bloquejada per ALLOW_CHANGES');
    if(!boundInt(data.count,1,max))throw Error('Nombre de CTRL incorrecte');
    return {id:specialId,command:'N:'+data.count+':'+specialId};
  }
  if(kind==='recover'){
    if(typeof data.original!=='string'||!/^\d{1,12}$/.test(data.original)||!boundInt(data.offset,0,49))throw Error('Recuperació no vàlida');
    return {id:specialId,command:'R:'+data.original+':'+data.offset+':'+specialId};
  }
  if(kind==='history'){
    if(typeof data.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||!boundInt(data.offset,0,999999))throw Error('Data o posició incorrectes');
    return {id:specialId,command:'H:'+data.date+':'+data.offset+':'+specialId};
  }
  if(!boundInt(seg,1,252)||seg===251||(seg!==252&&seg>max))throw Error('Seguidor no configurat');
  const id=newId();
  if(kind==='data'){
    if(seg===252)throw Error('Per consultar les dades cal seleccionar un CTRL');
    return {id,command:'D:'+seg+':'+id};
  }
  if(kind==='scan')return {id,command:seg+',38,0:'+id};
  if(kind!=='cmd'||!boundInt(fun,0,255)||!boundInt(val,0,999))throw Error('Funció o valor incorrectes');
  if(!ALLOWED_FUNS.has(fun))throw Error('Funció no disponible segons el manual i la configuració actual');
  if(fun===37 && (seg===252 || val>255))throw Error('F37: CTRL individual i valor de 0 a 255');
  if(fun===30 && val>7)throw Error('La funció 030 només admet valors de 0 a 7');
  if(!VALUE_FUNS.has(fun)&&val!==0)throw Error('Aquesta funció no admet cap valor addicional');
  if(seg===252&&FRAMES.has(fun))throw Error('Les funcions amb dades requereixen un CTRL individual');
  if(!READ_FUNS.has(fun)&&String(env.ALLOW_CHANGES||'NO').toUpperCase()!=='YES')throw Error('Funció de control bloquejada: activa ALLOW_CHANGES=YES només després de validar les proteccions');
  return {id,command:seg+','+fun+','+val+':'+id};
}
// Defensa local contra intents repetits. Es una proteccio complementaria;
// per a desplegament permanent cal Cloudflare Access / WAF de limitacio.
const failures=new Map();
function clientKey(req){return req.headers.get('cf-connecting-ip')||'anon';}
function blocked(req){const row=failures.get(clientKey(req));return !!(row&&row.count>=5&&row.until>Date.now());}
function badPass(req){const key=clientKey(req),now=Date.now();let row=failures.get(key);if(!row||now>row.until||now-row.first>60000)row={count:0,first:now,until:now+60000};row.count++;if(row.count>=5)row.until=now+120000;failures.set(key,row);if(failures.size>1000)failures.clear();}
function removeFailure(req){failures.delete(clientKey(req));}
export default {
  async fetch(request,env){
    try{
      const u=new URL(request.url);
      if(u.pathname==='/'&&request.method==='GET')return new Response(HTML,{headers:{...NO_CACHE,'Content-Type':'text/html; charset=utf-8',
        'Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"}});
      if(!u.pathname.startsWith('/api/'))return json(404,{ok:false,error:'Ruta no disponible'});
      if(!env.BLYNK_TOKEN||!env.PANEL_PASSWORD)return json(503,{ok:false,error:'Cal definir BLYNK_TOKEN i PANEL_PASSWORD al servidor'});
      if(blocked(request))return json(429,{ok:false,error:'Massa intents fallits: prova-ho mes tard'});
      const raw=request.headers.get('Authorization')||'';
      if(!raw.startsWith('Bearer ')||!limitedEqual(raw.slice(7),env.PANEL_PASSWORD)){
        badPass(request);return json(401,{ok:false,error:'Contrasenya incorrecta'});
      }
      removeFailure(request);
      if(u.pathname==='/api/config'&&request.method==='GET')return json(200,{ok:true,maxFollowers:settings(env),allowChanges:String(env.ALLOW_CHANGES||'NO').toUpperCase()==='YES'});
      if(u.pathname==='/api/status'&&request.method==='GET'){
        const body=await blynk(env,'/external/api/getAll');
        let all;try{all=JSON.parse(body);}catch(_){throw Error('Resposta de Blynk no llegible');}
        if(!all||typeof all!=='object'||Array.isArray(all)||all.error)throw Error('Blynk no ha retornat els datastreams esperats');
        return json(200,{ok:true,values:cleanValues(all)});
      }
      if(u.pathname==='/api/send'&&request.method==='POST'){
        // Evitar ordres des d'altres llocs web que no son el propi panell.
        const origin=request.headers.get('Origin');if(origin&&origin!==u.origin)return json(403,{ok:false,error:'Origen no autoritzat'});
        const ct=request.headers.get('Content-Type')||'';if(!ct.startsWith('application/json'))return json(415,{ok:false,error:'Format incorrecte'});
        const raw=await request.text();if(raw.length>1000)return json(413,{ok:false,error:'Ordre massa llarga'});
        let data;try{data=JSON.parse(raw);}catch(_){return json(400,{ok:false,error:'JSON incorrecte'});}
        let cmd;try{cmd=commandBody(data,env);}catch(e){return json(400,{ok:false,error:e.message});}
        await blynk(env,'/external/api/update',{V2:cmd.command});
        return json(200,{ok:true,...cmd,notice:'V2 actualitzat. Execucio pendent de resposta V3.'});
      }
      return json(404,{ok:false,error:'Operació desconeguda'});
    }catch(e){return json(502,{ok:false,error:e instanceof Error?e.message:'Error del servidor'});}
  }
};